<template><ContentWrap><h2>学员账号交付周期配置</h2><el-alert title="修改只影响尚未创建的新阶段计划，历史任务保留原时间。" type="info" show-icon class="mb-20px"/><el-form v-if="form" v-loading="loading" label-width="180px" class="max-w-600px"><el-form-item v-for="(name,index) in names" :key="name" :label="`S${index} 触发间隔`"><el-input-number v-model="form[name]" :min="0" :max="365"/><span class="ml-8px">天</span></el-form-item><el-button type="primary" v-hasPermi="['zsjos:student-delivery-config:update']" @click="save">保存</el-button></el-form><el-empty v-else description="配置加载失败"><el-button @click="load">重试</el-button></el-empty></ContentWrap></template>
<script setup lang="ts">import * as Api from '@/api/zsjos/studentDelivery';import {useMessage} from '@/hooks/web/useMessage';const message=useMessage(),loading=ref(false),form=ref<Api.StudentDeliveryConfig>(),names=['s0Days','s1Days','s2Days','s3Days','s4Days','s5Days','s6Days'] as const;const load=async()=>{loading.value=true;try{form.value=await Api.getStudentDeliveryConfig()}catch{form.value=undefined}finally{loading.value=false}};const save=async()=>{if(!form.value)return;await Api.updateStudentDeliveryConfig(form.value);message.success('已保存');await load()};onMounted(load)</script>
